export default class FamilyDom extends LightningElement {
 data={label:'A'};
 _step=0; _sent=-1; _errors=[];
 @api advance() {
  this._step += 1;
  const actions=[function(){this.data={label:'B'};}];
  try { if (actions[this._step-1]) actions[this._step-1].call(this); }
  catch(e) { this._errors.push({name:e.name,message:e.message}); }
  this._sent=-1; this._report();
 }
 renderedCallback() { this._report(); }
 _report() {
  const step=this._step;
  requestAnimationFrame(()=>requestAnimationFrame(()=>{
   if (step!==this._step || this._sent===step) return;
   this._sent=step;
   let value;
   try { value=(function(){ return {text:this.refs.child.textContent}; }).call(this); }
   catch(e) { value={exception:{name:e.name,message:e.message}}; }
   this.dispatchEvent(new CustomEvent('observe',{detail:{step,value,errors:this._errors.slice()}}));
  }));
 }
}

